//! Generates `apps/web/src/lib/generated/server.ts`, the TypeScript shape of
//! the `tiamud.v1` pieces owned by this crate: the `action.perform` payload
//! and the optional scene presentation annotation merged into
//! `scene.snapshot`/`sync.scene`. It fails when the committed file is stale.
//!
//! The `TS` derives are applied with `cfg_attr(test, ...)` and ts-rs is only a
//! dev-dependency, so neither enters the release dependency graph. Closed
//! vocabularies defined by `tiamud-core` or `tiamud-protocol` are named by a
//! type override and imported from their own generated files.
//!
//! Check (part of `cargo test --workspace`):
//!
//! ```sh
//! cargo test --locked -p tiamud-server web::typescript
//! ```
//!
//! Regenerate, then review the diff:
//!
//! ```sh
//! TIAMUD_UPDATE_GENERATED_PROTOCOL=1 cargo test --locked -p tiamud-server web::typescript
//! ```

use super::ActionPerformData;
use crate::runtime_content::{
    ProjectedAnchor, ProjectedEntityMedia, ProjectedFootprint, ProjectedPoses, ProjectedSource,
    ScenePresentation,
};
use std::path::PathBuf;
use ts_rs::{Config, TS};

const UPDATE_VARIABLE: &str = "TIAMUD_UPDATE_GENERATED_PROTOCOL";

fn generated_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../apps/web/src/lib/generated/server.ts")
}

/// Ordered declarations. Order is part of the generated output, so new types
/// are appended within their group rather than sorted implicitly.
fn declarations(config: &Config) -> Vec<String> {
    vec![
        // Client → server `action.perform`.
        ActionPerformData::decl(config),
        // Scene presentation annotation.
        ProjectedFootprint::decl(config),
        ProjectedAnchor::decl(config),
        ProjectedSource::decl(config),
        ProjectedPoses::decl(config),
        ProjectedEntityMedia::decl(config),
        ScenePresentation::decl(config),
    ]
}

/// Prefixes the `type` line of a declaration (after any JSDoc) with `export`.
fn exported(declaration: &str) -> String {
    let mut output = String::with_capacity(declaration.len() + 8);
    let mut exported = false;
    for line in declaration.lines() {
        if !exported && line.starts_with("type ") {
            output.push_str("export ");
            exported = true;
        }
        output.push_str(line);
        output.push('\n');
    }
    assert!(exported, "declaration without a type line: {declaration}");
    output
}

fn render() -> String {
    // JSON numbers decode to JavaScript numbers; every integer accepted or
    // projected here is bounded well below 2^53.
    let config = Config::new().with_large_int("number");
    let mut output = String::from(
        "// @generated by `cargo test -p tiamud-server web::typescript` from crates/mud-server.\n\
         // Do not edit by hand: run `TIAMUD_UPDATE_GENERATED_PROTOCOL=1 cargo test -p tiamud-server web::typescript`.\n\
         // These declarations describe the `tiamud.v1` wire shape; the browser still\n\
         // validates every inbound frame at runtime in `../protocol.ts`.\n\n\
         import type { AccountRole, SocialChannelName, StaffCapability, StaffProfileKey, StaffReportResolution } from './core';\n\
         import type { BoardKey } from './protocol';\n",
    );
    for declaration in declarations(&config) {
        output.push('\n');
        output.push_str(&exported(&declaration));
    }
    output
}

#[test]
fn generated_typescript_is_current() {
    let path = generated_path();
    let rendered = render();
    if std::env::var_os(UPDATE_VARIABLE).is_some_and(|value| value == "1") {
        std::fs::create_dir_all(path.parent().expect("generated path has a parent"))
            .expect("create generated directory");
        std::fs::write(&path, &rendered).expect("write generated TypeScript");
        return;
    }
    let committed = std::fs::read_to_string(&path).unwrap_or_default();
    assert!(
        committed == rendered,
        "{} is stale; run `{UPDATE_VARIABLE}=1 cargo test --locked -p tiamud-server web::typescript` and review the diff",
        path.display()
    );
}
